# LiteLLM proxy for Codex -> DeepSeek. Edit .env with your DEEPSEEK_API_KEY only.
$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot

$env:PYTHONUTF8 = "1"
$env:LITELLM_MASTER_KEY = "sk-litellm-local-codex"
$env:OPENAI_API_KEY = "sk-litellm-local-codex"

$envFile = Join-Path $PSScriptRoot ".env"
if (Test-Path $envFile) {
    Get-Content $envFile -Encoding UTF8 | ForEach-Object {
        $line = $_.Trim()
        if ($line -and -not $line.StartsWith("#") -and $line -match "^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$") {
            $val = $Matches[2].Trim().Trim('"').Trim("'")
            Set-Item -Path "Env:$($Matches[1])" -Value $val
        }
    }
}

if (-not $env:DEEPSEEK_API_KEY -or $env:DEEPSEEK_API_KEY -match "your-|你的") {
    Write-Host "ERROR: Set DEEPSEEK_API_KEY in .env (same folder as this script)." -ForegroundColor Red
    exit 1
}

Write-Host "Starting LiteLLM on http://127.0.0.1:4000"
Write-Host "Codex Bearer / OPENAI_API_KEY: sk-litellm-local-codex"
Write-Host "Model: deepseek-v4-pro"
Write-Host ""

litellm --config config.yaml

